// Clean the fetched HTML, truncate it, and assemble the Claude request.
const raw = String($json.data ?? $json.body ?? '');
const url = $('Fetch page').first().json.url || 'https://news.ycombinator.com';

const pageText = raw
  .replace(/<script[\s\S]*?<\/script>/gi, ' ')
  .replace(/<style[\s\S]*?<\/style>/gi, ' ')
  .replace(/<[^>]+>/g, ' ')
  .replace(/\s+/g, ' ')
  .trim()
  .slice(0, 15000);

const prompt = `You are a senior UX evaluator. Audit the web page below against Nielsen's 10 usability heuristics.
Assume the task: "complete the page's primary action as a first-time visitor."

For EACH of the 10 heuristics return:
- heuristic: the heuristic name
- score: 0-3 (0 = absent, 3 = excellent)
- severity: 0-4 (Nielsen severity of the worst issue; 0 = no issue)
- evidence: what on the page, concretely
- recommendation: one specific fix

Return ONLY valid minified JSON, no markdown fences, in this exact shape:
{"summary":"two-sentence verdict","findings":[{"heuristic":"","score":0,"severity":0,"evidence":"","recommendation":""}]}

PAGE URL: ${url}
PAGE CONTENT (may be truncated):
${pageText}`;

return [{ json: { url, requestBody: {
  model: 'claude-sonnet-4-5',
  max_tokens: 2000,
  messages: [{ role: 'user', content: prompt }]
} } }];

// Parse Claude's JSON, prioritise findings, render a Markdown report.
const resp = $json;
let text = '';
try { text = resp.content?.[0]?.text ?? resp.data?.content?.[0]?.text ?? ''; } catch (e) {}

let parsed;
try { parsed = JSON.parse(text); }
catch (e) { return [{ json: { error: 'Could not parse model JSON', raw: text } }]; }

const url = $('Build audit request').first().json.url;
const findings = (parsed.findings || [])
  .sort((a, b) => (b.severity - a.severity) || (a.score - b.score));

const total = findings.reduce((s, f) => s + (Number(f.score) || 0), 0);
const max = findings.length * 3;

let md = `# UX Heuristic Audit\n\n`;
md += `**Page:** ${url}\n`;
md += `**Generated:** ${new Date().toISOString().slice(0, 10)}\n`;
md += `**Heuristic score:** ${total}/${max}\n\n`;
md += `**Summary:** ${parsed.summary || ''}\n\n`;
md += `## Prioritised findings\n`;
findings.forEach((f, i) => {
  md += `\n### ${i + 1}. ${f.heuristic} — severity ${f.severity}/4 (score ${f.score}/3)\n`;
  md += `**Evidence:** ${f.evidence}\n\n`;
  md += `**Fix:** ${f.recommendation}\n`;
});

return [{ json: { url, heuristicScore: `${total}/${max}`, summary: parsed.summary, findings, report: md } }];
